import{_ as t,o,c as a,ag as r}from"./chunks/framework.em2JOrjF.js";const p=JSON.parse('{"title":"Time Tracking","description":"","frontmatter":{},"headers":[],"relativePath":"reference/concepts/time-tracking.md","filePath":"reference/concepts/time-tracking.md"}'),i={name:"reference/concepts/time-tracking.md"};function s(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="time-tracking" tabindex="-1">Time Tracking <a class="header-anchor" href="#time-tracking" aria-label="Permalink to &quot;Time Tracking&quot;">​</a></h1><p>Time entries are the atomic unit of VERA. Everything else — budgets, burn rates, financials — flows from the hours logged.</p><hr><h2 id="what-is-a-time-entry" tabindex="-1">What is a time entry? <a class="header-anchor" href="#what-is-a-time-entry" aria-label="Permalink to &quot;What is a time entry?&quot;">​</a></h2><p>A single logged record of work. Every entry has exactly five meaningful fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>Who did the work</td><td>Alice (resolved from her Slack ID)</td></tr><tr><td><code>project_id</code></td><td>What project it&#39;s for</td><td>Nike Rebrand</td></tr><tr><td><code>task_id</code></td><td>What type of work</td><td>Development</td></tr><tr><td><code>hours</code></td><td>How many hours</td><td>4.5 (stored as decimal)</td></tr><tr><td><code>date</code></td><td>When it happened</td><td>2026-03-28</td></tr><tr><td><code>notes</code></td><td>Optional context</td><td>&quot;Fixed auth bug on login page&quot;</td></tr></tbody></table><p>There&#39;s also an <code>id</code> — a permanent sequential number assigned when the entry is created. Use this ID to edit or delete the entry later.</p><hr><h2 id="task-is-always-required" tabindex="-1">Task is always required <a class="header-anchor" href="#task-is-always-required" aria-label="Permalink to &quot;Task is always required&quot;">​</a></h2><p>VERA will never log time without a task type. If you don&#39;t specify one, VERA will ask.</p><blockquote><p><strong>User</strong>: &quot;4 hours on Nike&quot;</p><p><strong>VERA</strong>: &quot;What type of work? (Development, Design, QA, Project Management, Client Meeting, Admin)&quot;</p></blockquote><p>This is not optional. Tasks are what connect hours to cost categories, envelopes, and billability.</p><hr><h2 id="hours-format" tabindex="-1">Hours format <a class="header-anchor" href="#hours-format" aria-label="Permalink to &quot;Hours format&quot;">​</a></h2><p>Always use hours-and-minutes format in conversation:</p><ul><li>✅ &quot;4h 30m&quot;</li><li>✅ &quot;2h&quot;</li><li>✅ &quot;45m&quot;</li><li>❌ &quot;4.5 hours&quot;</li><li>❌ &quot;4.5h&quot;</li></ul><p>VERA stores hours as a decimal internally (4.5), but always presents and accepts them as <code>4h 30m</code>.</p><hr><h2 id="billable-vs-non-billable-tasks" tabindex="-1">Billable vs. non-billable tasks <a class="header-anchor" href="#billable-vs-non-billable-tasks" aria-label="Permalink to &quot;Billable vs. non-billable tasks&quot;">​</a></h2><p>Each task type has an <code>is_billable</code> flag. Billable tasks generate revenue. Non-billable tasks are tracked for cost purposes only.</p><p>Example: &quot;Admin&quot; is typically non-billable. &quot;Development&quot; is typically billable. The billability is set per task type, not per entry.</p><p>Project type also affects this: Pro Bono projects have <code>is_billable = false</code> regardless of task type.</p><hr><h2 id="logging-for-others" tabindex="-1">Logging for others <a class="header-anchor" href="#logging-for-others" aria-label="Permalink to &quot;Logging for others&quot;">​</a></h2><p>By default, Users can only log time for themselves. Managers can log time for people on their assigned projects (e.g. via <code>log_sick_day</code> or <code>log_leave</code>). Owners can log for anyone.</p><p>When logging via <code>@mention</code>, VERA uses the Slack user ID from the mention — name-based matching is less reliable and not used.</p><hr><h2 id="editing-and-deleting-entries" tabindex="-1">Editing and deleting entries <a class="header-anchor" href="#editing-and-deleting-entries" aria-label="Permalink to &quot;Editing and deleting entries&quot;">​</a></h2><p>Use the entry&#39;s <code>id</code> to reference it:</p><ul><li><code>edit_entry</code> — change hours or notes. Owners can edit any entry; Users can only edit their own.</li><li><code>delete_entry</code> — permanently removes the entry. Same permission rules.</li></ul><p>There is no &quot;soft delete.&quot; Deleted entries are gone. VERA will warn you before the deletion.</p><hr><h2 id="how-entries-relate-to-budgets" tabindex="-1">How entries relate to budgets <a class="header-anchor" href="#how-entries-relate-to-budgets" aria-label="Permalink to &quot;How entries relate to budgets&quot;">​</a></h2><p>Logging time does not deduct from an envelope automatically in a blocking sense — but VERA tracks the relationship:</p><ul><li><code>get_project_status</code> shows hours logged vs. task budgets</li><li><code>get_estimates_vs_actuals</code> compares allocated hours to actual logged hours</li><li>Morning summaries flag people whose logged hours exceed their envelope</li></ul><p>The system is transparent, not restrictive. You can always log more than your budget — the alerts tell you when that&#39;s happening.</p><hr><h2 id="time-entry-ids" tabindex="-1">Time entry IDs <a class="header-anchor" href="#time-entry-ids" aria-label="Permalink to &quot;Time entry IDs&quot;">​</a></h2><p>Every entry gets a permanent sequential ID assigned at creation. IDs are never reused, even if an entry is deleted. This means:</p><ul><li>You can always reference entry <code>#42</code> in conversation: &quot;Edit entry 42&quot;</li><li>VERA confirms the ID when logging: &quot;Logged 4h on Nike Rebrand (Development) (ID: 42)&quot;</li><li>Historical audit trails are reliable</li></ul><hr><h2 id="the-person-field-deprecated" tabindex="-1">The person field (deprecated) <a class="header-anchor" href="#the-person-field-deprecated" aria-label="Permalink to &quot;The person field (deprecated)&quot;">​</a></h2><p>The schema includes a <code>person</code> column (column C in <code>01. Time Entries</code>), but it is deprecated and always written as an empty string. Person is resolved from <code>user_id</code> when needed. Do not rely on this column in reporting formulas — always join via <code>user_id</code>.</p><hr><h2 id="protected-time-off-projects" tabindex="-1">Protected time-off projects <a class="header-anchor" href="#protected-time-off-projects" aria-label="Permalink to &quot;Protected time-off projects&quot;">​</a></h2><p>Three special projects exist for absence tracking:</p><ul><li><strong>Out of Office</strong> — for PTO/vacation</li><li><strong>Sick</strong> — for sick days</li><li><strong>Leave</strong> — for unpaid or extended leave</li></ul><p>Users cannot log directly to these projects. Time is only recorded here through the formal request and approval workflow. See <a href="/vera-docs/reference/workflows/time-off.html">Time Off Requests</a>.</p>',48)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
